-- Hand-written (Prisma does not model CHECK constraints, so no drift).

-- An event cannot end before it starts.
ALTER TABLE "Event"
  ADD CONSTRAINT "Event_dates_check"
  CHECK ("endsAt" IS NULL OR "endsAt" >= "startsAt");

-- A report points to a canonical report exactly when it is a DUPLICATE,
-- and never to itself.
ALTER TABLE "Report"
  ADD CONSTRAINT "Report_duplicate_check"
  CHECK (
    ("status" = 'DUPLICATE') = ("duplicateOfReportId" IS NOT NULL)
    AND ("duplicateOfReportId" IS NULL OR "duplicateOfReportId" <> "id")
  );

